USE loja_tintas_materiais;

-- Como o volume foi calibrado (numeros informados pela loja):
--   ~500 unidades vendidas por mes e ~R$ 20 mil de faturamento por mes,
--   2 funcionarios, troca em ate 2 semanas, catalogo das listas do PDV.
-- Periodo simulado: 02/01/2026 a 30/06/2026 (segunda a sabado; domingo fechado).
-- Resultado desta massa (vendas CONCLUIDAS):
--   01/2026: 165 vendas concluidas | R$  20643.70 |  608 unidades
--   02/2026: 124 vendas concluidas | R$  22094.20 |  476 unidades
--   03/2026: 156 vendas concluidas | R$  17250.50 |  558 unidades
--   04/2026: 146 vendas concluidas | R$  19419.50 |  535 unidades
--   05/2026: 135 vendas concluidas | R$  14247.20 |  515 unidades
--   06/2026: 155 vendas concluidas | R$  19490.90 |  522 unidades
-- Totais: 940 vendas (881 concluidas, 31 canceladas,
--         28 orcamentos), 2199 itens, 905 pagamentos,
--         121 clientes (10 sem compras), 3 funcionarios (1 desligado).
-- Dados pessoais 100% ficticios. Produtos, codigos, EAN e NCM: reais (listas do PDV).

